import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // textured plane
  const planeWidth = 1.6; // based on 512x320 aspect
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    transparent: true,
  });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // async texture load (sync function)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 96,
      color: (config.intent?.visualSpec?.colors?.paper) || '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    root.add(txtObj);
  }

  // cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // event handlers placeholder
  root.userData.handlers = {};

  // cleanup routine
  root.userData.cleanup = () => {
    // dispose geometry & material
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();

    // primitive cleanups
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }

    // dispose any child text objects that expose cleanup
    for (const child of root.children) {
      if (child.userData && typeof child.userData.cleanup === 'function') {
        child.userData.cleanup();
      }
    }

    // kill any GSAP timelines (none in this node but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
